    <script>
        function logPrintEvent() {

            var ptrNo = $('#ptr-no').text();
            $.ajax({
                url: '/print-event',
                method: 'post',
                data: {
                    documentID: ptrNo,
                    printedModule: 'PTR'
                },
                success: function(response) {},
                error: function(xhr, status, error) {
                    console.error('Error logging print event:', error);
                }
            });
        }

        window.onbeforeprint = logPrintEvent;
    </script>
